import { MutationTree } from "vuex";
import { FormState, FormFieldVue, AttributeValue } from "../../interface/FormInterface";
import { FormField } from "../../interface/FormInterface";
import { getFieldEvents } from "../getForm/getEvents";
import { getFieldAttributes } from "../getForm/getAttributes";

export const getMutations = (): MutationTree<FormState> => {
    return {
        setFormInstance(state: FormState, form: Gikam.component.Form) {
            state.formInstance = form;
        },

        setActiveField(state: FormState, field: FormFieldVue) {
            if (state.activeField === field) {
                return;
            }
            if (state.activeField) {
                state.activeField.active = false;
            }
            state.activeField = field;
        },

        setActiveFieldEditorAttr(state: FormState, Field: FormFieldVue) {
            state.activeFieldEditorAttrs = getFieldAttributes(Field);
        },

        setActiveFieldEditorEvents(state: FormState, Field: FormFieldVue) {
            state.activeFieldEditorEvents = getFieldEvents(Field).map(item => {
                item.value = Field[item.attribute as keyof FormField]?.toString();
                return item;
            });
        },

        updateFormDate(state: FormState, attribute: AttributeValue) {
            const activeField = state.activeField as GeneralObject;
            activeField[attribute.attribute] = attribute.value;
        },

        saveFields(state: FormState) {
            state.options = state.tempOptions;
        }
    };
};
