import { Vue } from "@/com/sunwayworld/framework/gikam/vue";
import { Constant } from "@/com/sunwayworld/framework/constant/Constant";
import router from "../router/pageDesignRouter";
import store, { PageDesignMutations } from "../store/pageDesignStore";
import App from "../vue/App.vue";

interface Menu {
    id: string;
    text: string;
    children?: Menu[];
}

export class PageDesign {
    private model!: Vue;

    constructor(options: Gikam.component.I18NOptions) {
        this.initI18N(options)
            .initLoginUser()
            .initModel()
            .initMenuTree()
            .initWorkspace();
    }

    private initI18N(options: Gikam.component.I18NOptions): PageDesign {
        Gikam.create("I18N", options);
        return this;
    }

    initMenuTree(): PageDesign {
        Gikam.post<Menu[]>(Constant.IFM_CONTEXT + "/secure/core/module/sys/menus/tree/root").done(data => {
            store.commit(PageDesignMutations.UPDATE_MENU_TREE, data);
        });
        return this;
    }

    private initModel(): PageDesign {
        Vue.config.productionTip = false;
        this.model = new Vue({
            router,
            store,
            render: h => h(App)
        }).$mount("#app");
        return this;
    }

    private initWorkspace(): PageDesign {
        this.model.$nextTick(() => {
            const workspace: Workspace = {
                window: Gikam.create<Gikam.component.WindowOptions, Gikam.component.Window>("window", {
                    renderTo: document.getElementById("canvas")
                }) as Gikam.component.Window
            };
            window.workspace = workspace;
            store.commit(PageDesignMutations.UPDATE_WORKSPACE, workspace);
        });
        return this;
    }

    private initLoginUser(): PageDesign {
        Gikam.getText(Gikam.IFM_CONTEXT + "/core/module/sys/logins/account").done(result => {
            const user = JSON.parse(result) as User;
            user.isAdmin = "sysAdmin".indexOf(user.userType) >= 0;
            window.workspace.user = user;
        });
        return this;
    }
}
