import { BaseAttribute, BaseEvent } from "../../../main/interface/PageDesignInterface";

export const getFormAttribute = (options: Gikam.component.FormOptions): BaseAttribute[] => {
    return [
        {
            title: "id",
            attribute: "id",
            value: options.id || ""
        },
        {
            title: "请求地址",
            attribute: "url",
            value: options.url || ""
        },
        {
            title: "字段",
            attribute: "fields",
            editorType: "object",
            value: "fields"
        },
        {
            title: "宽度自适应",
            attribute: "titleWidthAuto",
            value: options.titleWidthAuto || false,
            editorType: "select"
        },
        {
            title: "service实现类",
            attribute: "service",
            value: options.service || ""
        },
        {
            title: "是否自动保存",
            attribute: "autoSave",
            value: options.autoSave || true,
            editorType: "select"
        },
        {
            title: "标题对齐方式",
            attribute: "titleAlign",
            value: options.titleAlign || "right"
        },
        {
            title: "字段宽度",
            attribute: "titleWidth",
            value: options.titleWidth,
            editorType: "number"
        }
    ];
};

export const getFormEvent = (options: Gikam.component.FormOptions): BaseEvent[] => {
    return [
        {
            value: options.onLoadSuccess?.toString() || "",
            attribute: "onLoadSuccess"
        },
        {
            value: options.onRendered?.toString() || "",
            attribute: "onRendered"
        },
        {
            value: options.onInserted?.toString() || "",
            attribute: "onInserted"
        },
        {
            value: options.onUpdated?.toString() || "",
            attribute: "onUpdated"
        },
        {
            value: options.onBeforeUpdate?.toString() || "",
            attribute: "onBeforeUpdate"
        }
    ];
};
