

















import { Component, Vue, Action, State } from "sunway-vue";
import ControlImg from "../img/ControlImg.vue";
import SaveImg from "@/com/sunwayworld/components/img/SaveImg.vue";
import SubmitImg from "@/com/sunwayworld/components/img/SubmitImg.vue";
import { PageDesignActions } from "../../store/pageDesignStore";

@Component({
    components: {
        ControlImg,
        SaveImg,
        SubmitImg
    }
})
export default class DesignHeader extends Vue {
    @Action(PageDesignActions.SAVE_FILE)
    private saveFile!: () => void;

    @Action(PageDesignActions.SUBMIT_FILE)
    private submitFile!: () => void;

    @State
    private fileEditing!: boolean;

    get isEditing(): boolean {
        return this.fileEditing;
    }
}
