import { Vuex } from "@/com/sunwayworld/framework/gikam/vue";
import { FormState } from "../interface/FormInterface";
import { getState } from "./state/state";
import { getMutations } from "./mutations/mutations";
import { getActions } from "./actions/actions";

export const getStore = (form: Gikam.component.Form) => {
    return new Vuex.Store<FormState>({
        state: getState(form),
        mutations: getMutations(),
        actions: getActions()
    });
};
