import {
    Column,
    SelectColumn,
    ColumnTypeEnum,
    NumberColumn,
    ChooseColumn,
    DateColumn,
    DateTimeColumn,
    YearColumn
} from "../../interface/Column";
import { ColumnAttrEditor } from "../../interface/ColumnAttrEditor";
import { SelectUtils } from "@/com/sunwayworld/framework/utils/SelectUtils";

// 复选框类型
const getCheckboxColumnAttrs = (column: Column): ColumnAttrEditor[] => {
    return [
        {
            title: "列名称",
            attribute: "title",
            editorType: "text",
            value: "复选框",
            readonly: true
        },
        {
            title: "默认宽度",
            attribute: "width",
            editorType: "text",
            value: column.width,
            readonly: true
        }
    ];
};

// 索引类型
const getIndexColumnAttrs = (column: Column): ColumnAttrEditor[] => {
    return [
        {
            title: "列名称",
            attribute: "title",
            editorType: "text",
            value: "序列",
            readonly: true
        },
        {
            title: "默认宽度",
            attribute: "width",
            editorType: "number",
            value: column.width,
            readonly: true
        }
    ];
};

//获取通用列属性
const getCommonColumnAttrs = (column: Column): ColumnAttrEditor[] => {
    return [
        {
            title: "取值字段",
            attribute: "field",
            editorType: "text",
            value: column.field
        },
        {
            title: "列名称",
            attribute: "title",
            editorType: "text",
            value: Gikam.propI18N(column.title)
        },
        {
            title: "默认宽度",
            attribute: "width",
            editorType: "number",
            value: column.width
        }
    ];
};

//获取下拉框编辑时的属性
const getSelectAttrs = (column: SelectColumn): ColumnAttrEditor[] => {
    return getCommonColumnAttrs(column).concat([
        {
            title: "数据源",
            attribute: "category",
            editorType: "select",
            value: column.category
        }
    ]);
};

// 数字类型
const getNumberColumnAttrs = (column: NumberColumn): ColumnAttrEditor[] => {
    return getCommonColumnAttrs(column).concat([
        {
            title: "是否显示箭头",
            attribute: "hasArrow",
            editorType: "select",
            value: false,
            items: SelectUtils.yesNo
        },
        {
            title: "是否为整数",
            attribute: "isInteger",
            editorType: "select",
            items: SelectUtils.yesNo,
            value: false
        },
        {
            title: "取值范围",
            attribute: "range",
            editorType: "text"
        }
    ]);
};

// choose类型
const getChooseColumnAttrs = (column: ChooseColumn): ColumnAttrEditor[] => {
    return getCommonColumnAttrs(column).concat([
        {
            title: "是否单选",
            attribute: "single",
            editorType: "select",
            items: SelectUtils.yesNo,
            value: false
        },
        {
            title: "是否可清除",
            attribute: "cleanable",
            editorType: "select",
            items: SelectUtils.yesNo,
            value: false
        }
    ]);
};

const getDateTimeColumnAttrs = (column: DateTimeColumn | YearColumn): ColumnAttrEditor[] => {
    return getCommonColumnAttrs(column).concat([
        {
            title: "是否可输入",
            attribute: "editable",
            items: SelectUtils.yesNo,
            value: false
        },
        {
            title: "可选日期范围",
            attribute: "dateRange",
            editorType: "text"
        }
    ]);
};

const getDateColumnAttrs = (column: DateColumn): ColumnAttrEditor[] => {
    return getCommonColumnAttrs(column).concat([
        {
            title: "是否选择时分秒",
            attribute: "selectTime",
            editorType: "select",
            items: SelectUtils.yesNo,
            value: false
        }
    ]);
};

export const getColumnAttributes = (column: Column): ColumnAttrEditor[] => {
    if (column.checkbox) {
        return getCheckboxColumnAttrs(column);
    }
    if (column.index) {
        return getIndexColumnAttrs(column);
    }

    switch (column.type) {
        case ColumnTypeEnum.SELECT: {
            return getSelectAttrs(column as SelectColumn);
        }
        case ColumnTypeEnum.NUMBER: {
            return getNumberColumnAttrs(column as NumberColumn);
        }
        case ColumnTypeEnum.CHOOSE: {
            return getChooseColumnAttrs(column as ChooseColumn);
        }
        case ColumnTypeEnum.DATE: {
            return getDateColumnAttrs(column as DateColumn);
        }
        case ColumnTypeEnum.YEAR: {
            return getDateTimeColumnAttrs(column as YearColumn);
        }
        default: {
            return getCommonColumnAttrs(column);
        }
    }
};
