export enum ColumnTypeEnum {
    SELECT = "select",
    TEXT = "text",
    CHOOSE = "choose",
    NUMBER = "number",
    DATE = "date",
    DATE_TIME = "dateTime",
    TIME = "time",
    YEAR = "year",
    INSERTABLE_SELECT = "insertableSelect",
    CHECKBOX = "checkbox",
    SIMPLE_CHECKBOX = "simpleCheckbox",
    TEXTAREA = "textarea",
    LINK = "link",
    IMAGE = "image",
    CKEDITOR = "ckeditor",
    SCRIPT_FIELD = "scriptField",
    COMBO_BOX = "comboBox",
    CRON = "cron",
    RICH_TEXT = "richText",
    RICH_TEXT_CHOOSE = "richTextChoose"
}

export interface Column {
    title: string;
    field: string;
    type?: string;
    editor?: boolean;
    width?: number;
    checkbox?: boolean;
    index?: boolean;
    _id?: number;
}

export interface SelectColumn extends Column {
    type: "select";
    category: string;
}

export interface NumberColumn extends Column {
    type: "number";
    hasArrow?: boolean;
    isInteger?: boolean;
    range?: string | boolean;
}

export interface ChooseColumn extends Column {
    type: "choose";
    category: string;
    single?: true;
    cleanable?: boolean;
}

export interface DateColumn extends Column {
    type: "date";
    editable?: boolean;
    selectTime?: boolean;
    dateRange?: string[];
}

export interface DateTimeColumn extends Column {
    type: "dateTime";
}

export interface YearColumn extends Column {
    type: "year";
}
