import { GridState, GridColumn } from "../../interface/GridInterface";
import { getActivatedCompState } from "@/com/sunwayworld/framework/base/BaseActivatedCompStore";

const formatterColumns = (columns: GridColumn[]): GridColumn[] => {
    columns.forEach((item, index) => {
        if (item.checkbox == true) {
            item.title = "复选框";
        }
        if (item.index == true) {
            item.title = "序列";
        }
        if (index === 0) {
            item.active = true;
        }
    });
    return columns;
};

export const getState = (grid: Gikam.component.Grid): GridState => {
    const state: GridState = {
        gridInstance: grid,
        rawColumns: void 0,
        columns: grid.store.state.columns,
        activeColumn: void 0,
        activeColumnEditorEvents: void 0,
        tempColumns: formatterColumns(Gikam.deepExtend(grid.store.state.columns))
    };
    return getActivatedCompState(state);
};
