import { BaseAttribute, BaseEvent } from "../../../main/interface/PageDesignInterface";
import { ObjectUtils } from "@/com/sunwayworld/framework/utils/ObjectUtils";
import { SelectUtils } from "@/com/sunwayworld/framework/utils/SelectUtils";

// eslint-disable-next-line complexity
export const getGridAttribute = (options: Gikam.component.GridOptions): BaseAttribute[] => {
    return [
        {
            title: "id",
            attribute: "id",
            value: options.id || ""
        },
        {
            title: "请求地址",
            attribute: "url",
            value: options.url || ""
        },
        {
            title: "列",
            attribute: "columns",
            editorType: "object",
            value: "columns"
        },
        {
            title: "是否前端筛选",
            attribute: "serverSearch",
            value: ObjectUtils.getFinalValue(options.serverSearch, false),
            editorType: "select",
            items: SelectUtils.yesNo
        },
        {
            title: "查询条件",
            attribute: "requestData",
            value: Gikam.parseObjectToString(options.requestData || {})
        },
        {
            title: "高度",
            attribute: "height",
            value: options.height || 400,
            editorType: "number"
        },
        {
            title: "高度是否充满父容器",
            attribute: "fill",
            value: ObjectUtils.getFinalValue(options.fill, false),
            editorType: "select",
            items: SelectUtils.yesNo
        },
        {
            title: "按钮工具栏对齐方式",
            attribute: "toolbarAlign",
            value: options.toolbarAlign || "right",
            editorType: "select",
            items: SelectUtils.align
        },
        {
            title: "列是否支持拖动",
            attribute: "columnResize",
            value: options.columnResize || true,
            editorType: "select",
            items: SelectUtils.yesNo
        },
        {
            title: "行分组",
            attribute: "group",
            value: options.group ? Gikam.parseObjectToString(options.group) : ""
        },
        {
            title: "显示快捷查询",
            attribute: "filter",
            value: ObjectUtils.getFinalValue(options.filter, true),
            editorType: "select",
            items: SelectUtils.yesNo
        },
        {
            title: "默认展开快捷查询",
            attribute: "filterOpen",
            value: ObjectUtils.getFinalValue(options.filterOpen, false),
            editorType: "select",
            items: SelectUtils.yesNo
        },
        {
            title: "通用按钮",
            attribute: "generalButtonGroup",
            value: options.generalButtonGroup || ["export", "refresh"]
        },
        {
            title: "是否分页",
            attribute: "page",
            value: ObjectUtils.getFinalValue(options.page, true),
            editorType: "select",
            items: SelectUtils.yesNo
        },
        {
            title: "每页数量",
            attribute: "pageSize",
            value: ObjectUtils.getFinalValue(options.pageSize, 50),
            editorType: "number"
        },
        {
            title: "是否自动保存",
            attribute: "autoSave",
            value: ObjectUtils.getFinalValue(options.autoSave, true),
            editorType: "select",
            items: SelectUtils.yesNo
        },
        {
            title: "排序",
            attribute: "order",
            value: ObjectUtils.getFinalValue(options.autoSave, true),
            editorType: "select",
            items: SelectUtils.yesNo
        },
        {
            title: "初始化或刷新时触发",
            attribute: "fieldChangeFlag",
            value: ObjectUtils.getFinalValue(options.autoSave, true),
            editorType: "select",
            items: SelectUtils.yesNo
        },
        {
            title: "激活行时勾选复选框",
            attribute: "checkOnActive",
            value: ObjectUtils.getFinalValue(options.checkOnActive, true),
            editorType: "select",
            items: SelectUtils.yesNo
        },
        {
            title: "激活行时取消其他行勾选",
            attribute: "checkOneOnActive",
            value: ObjectUtils.getFinalValue(options.checkOnActive, true),
            editorType: "select",
            items: SelectUtils.yesNo
        },
        {
            title: "初始化数据查询",
            attribute: "initRequest",
            value: ObjectUtils.getFinalValue(options.initRequest, true),
            items: SelectUtils.yesNo
        },
        {
            title: "隐式编辑器",
            attribute: "editorInvisible",
            value: ObjectUtils.getFinalValue(options.editorInvisible, true),
            editorType: "select",
            items: SelectUtils.yesNo
        },
        {
            title: "单元格文本换行",
            attribute: "textLineFeed",
            editorType: "select",
            items: SelectUtils.yesNo,
            value: ObjectUtils.getFinalValue(options.textLineFeed, true)
        },
        {
            title: "选中行时显示角标",
            attribute: "showCheckedNum",
            editorType: "select",
            items: SelectUtils.yesNo,
            value: ObjectUtils.getFinalValue(options.showCheckedNum, true)
        },
        {
            title: "导出文件名",
            attribute: "name",
            value: ObjectUtils.getFinalValue(options.name, "导出文件")
        }
    ];
};

export const getGridOther = (options: Gikam.component.GridOptions): BaseEvent[] => {
    return [
        {
            attribute: "deleteFormatter",
            value: options.deleteFormatter?.toString() || ""
        },
        {
            attribute: "activateFormatter",
            value: options.activateFormatter?.toString() || ""
        }
    ];
};

// eslint-disable-next-line complexity
export const getGridEvent = (options: Gikam.component.GridOptions): BaseEvent[] => {
    return [
        {
            value: options.onBeforeRefresh?.toString() || "",
            attribute: "onBeforeRefresh"
        },
        {
            value: options.onBeforeLoad?.toString() || "",
            attribute: "onBeforeLoad"
        },
        {
            value: options.onCellClick?.toString() || "",
            attribute: "onCellClick"
        },
        {
            value: options.onRendered?.toString() || "",
            attribute: "onRendered"
        },
        {
            value: options.onRowActive?.toString() || "",
            attribute: "onRowActive"
        },
        {
            value: options.onSelect?.toString() || "",
            attribute: "onSelect"
        },
        {
            value: options.onLoadSuccess?.toString() || "",
            attribute: "onLoadSuccess"
        },
        {
            value: options.onBeforeUpdate?.toString() || "",
            attribute: "onBeforeUpdate"
        },
        {
            value: options.onUpdated?.toString() || "",
            attribute: "onUpdated"
        },
        {
            value: options.onBeforeDelete?.toString() || "",
            attribute: "onBeforeDelete"
        },
        {
            value: options.onBeforeActivate?.toString() || "",
            attribute: "onBeforeActivate"
        },
        {
            value: options.onBeforeSuspend?.toString() || "",
            attribute: "onBeforeSuspend"
        },
        {
            value: options.onUnSelect?.toString() || "",
            attribute: "onUnSelect"
        },
        {
            value: options.onAllSelect?.toString() || "",
            attribute: "onAllSelect"
        },
        {
            value: options.onUnAllSelect?.toString() || "",
            attribute: "onUnAllSelect"
        },
        {
            value: options.onCheckboxClick?.toString() || "",
            attribute: "onCheckboxClick"
        },
        {
            value: options.onAfterChoose?.toString() || "",
            attribute: "onAfterChoose"
        },
        {
            value: options.onBeforeEditorRender?.toString() || "",
            attribute: "onBeforeEditorRender"
        }
    ];
};
