import { GetterTree } from "vuex";
import { GridState } from "../../interface/GridInterface";
import { ColumnAttrEditor } from "../../interface/ColumnAttrEditor";
import { getColumnAttributes } from "../getGrid/getColumnAttributes";

export const getGetters = (): GetterTree<GridState, GridState> => {
    return {
        activeColumnEditorAttrs(state: GridState): ColumnAttrEditor[] {
            if (state.activeColumn) {
                return getColumnAttributes(state.activeColumn);
            }
            return [];
        }
    };
};
