















import { Component } from "sunway-vue";
import { SelectEditorProps } from "@/com/sunwayworld/components/editor/interface/Editor";
import BaseEditor from "@/com/sunwayworld/components/editor/BaseEditor.vue";
import SelectArrowDown from "@/com/sunwayworld/components/img/SelectArrowDown.vue";
import SelectPicker from "./SelectPicker.vue";

import SelectItem = Gikam.component.SelectItem;
import { ObjectUtils } from "../../../framework/utils/ObjectUtils";

@Component({
    components: {
        SelectArrowDown,
        SelectPicker
    }
})
export default class SelectEditor extends BaseEditor<SelectEditorProps> {
    private active = false;

    private clickHandle() {
        this.active = true;
    }

    private getPropData() {
        return {
            items: this.items,
            value: this.value,
            target: this.$refs.target
        };
    }

    get items(): SelectItem[] {
        return this.props.items || [];
    }

    get selectText() {
        if (ObjectUtils.isNotEmpty(this.value) && ObjectUtils.isNotEmpty(this.items)) {
            return this.items.filter(item => {
                return item.value === this.value;
            })[0].text;
        }
    }

    private selectItem(item: SelectItem) {
        this.active = false;
        this.value = item.value;
    }
}
