
import CompMask from "@/com/sunwayworld/components/compmask/CompMask.vue";
import { Component, Vue } from "sunway-vue";

import { getStore } from "@/com/sunwayworld/components/form/store/formStore";

@Component
export default class FormMask extends CompMask {
    editFields() {
        // eslint-disable-next-line @typescript-eslint/no-this-alias
        const _this = this;
        new Vue({
            el: Gikam.createDom("div", document.body),
            store: getStore(this.comp as Gikam.component.Form),
            components: {
                FieldsDesginBox: () => import("@/com/sunwayworld/components/form/fields/FieldsDesignBox.vue")
            },
            render(h) {
                return h("FieldsDesginBox", {
                    on: {
                        confirmUpdateFields(form: Gikam.component.Form) {
                            _this.$emit("updateFormFields", form);
                        }
                    }
                });
            }
        });
    }

    public modifyCompObjectAttr(attr: string) {
        if (attr === "fields") {
            this.editFields();
        }
    }
}
