import { GridColumn, ColumnEvent } from "../../interface/GridInterface";
import { ColumnTypeEnum } from "../../interface/Column";

// text事件
const getTextEvents = (column: ColumnEvent): ColumnEvent[] => {
    return [
        {
            attribute: "onChange",
            value: column.onChange?.toString() || ""
        },
        {
            attribute: "onKeyDown",
            value: column.onKeyDown?.toString() || ""
        },
        {
            attribute: "onInput",
            value: column.onInput?.toString() || ""
        },
        {
            attribute: "textStyleFormatter",
            value: column.textStyleFormatter?.toString() || ""
        }
    ];
};

// select/RichText/insertableSelect/number/DateTime/Textarea/Ckeditor/ScriptField/ComboBox/time/year事件
const getCommonEvents = (column: ColumnEvent): ColumnEvent[] => {
    return [
        {
            attribute: "onChange",
            value: column.onChange?.toString() || ""
        }
    ];
};

// checkbox事件
const getCheckboxColumnEvents = (column: ColumnEvent): ColumnEvent[] => {
    return [
        {
            attribute: "onChange",
            value: column.onChange?.toString() || ""
        },
        {
            attribute: "onAllClick",
            value: column.onAllClick?.toString() || ""
        },
        {
            attribute: "onClick",
            value: column.onClick?.toString() || ""
        }
    ];
};

// data事件
const getDataColumnEvents = (column: ColumnEvent): ColumnEvent[] => {
    return [
        {
            attribute: "onChange",
            value: column.onChange?.toString() || ""
        },
        {
            attribute: "onBeforeSelect",
            value: column.onBeforeSelect?.toString() || ""
        }
    ];
};

// RichTextChoose事件
const getRichTextChooseColumnEvents = (column: ColumnEvent): ColumnEvent[] => {
    return [
        {
            attribute: "onChange",
            value: column.onChange?.toString() || ""
        },
        {
            attribute: "onBeforeChoose",
            value: column.onBeforeChoose?.toString() || ""
        },
        {
            attribute: "onAfterChoose",
            value: column.onAfterChoose?.toString() || ""
        }
    ];
};

// choose事件
const getChooseColumnEvents = (column: ColumnEvent): ColumnEvent[] => {
    return getRichTextChooseColumnEvents(column).concat([
        {
            attribute: "formatter",
            value: column.formatter?.toString() || ""
        },
        {
            attribute: "onClean",
            value: column.onClean?.toString() || ""
        },
        {
            attribute: "onChoose",
            value: column.onChoose?.toString() || ""
        }
    ]);
};

export const getColumnEvents = (column: GridColumn): ColumnEvent[] => {
    if (!column) {
        return getTextEvents(column);
    }
    if (column.index || column.checkbox) return [];
    if (!column.type) {
        return getTextEvents(column);
    }
    switch (column.type) {
        case ColumnTypeEnum.CHECKBOX: {
            return getCheckboxColumnEvents(column);
        }
        case ColumnTypeEnum.DATE: {
            return getDataColumnEvents(column);
        }
        case ColumnTypeEnum.RICH_TEXT: {
            return getRichTextChooseColumnEvents(column);
        }
        case ColumnTypeEnum.CHOOSE: {
            return getChooseColumnEvents(column);
        }
        default:
            return getCommonEvents(column);
    }
};
