import { MutationTree } from "vuex";
import { GridState, GridColumn, GridColumnVue } from "../../interface/GridInterface";
import { getColumnAttributes } from "../getGrid/getColumnAttributes";
import { getColumnEvents } from "../getGrid/getColumnEvents";
import { getActivatedCompMutations } from "@/com/sunwayworld/framework/base/BaseActivatedCompStore";

const formatterColumns = (columns: GridColumn[]): GridColumn[] => {
    columns.forEach(item => {
        if (item.checkbox === true) {
            delete item.title;
        }
        if (item.index === true) {
            delete item.title;
        }
        if (item.active) delete item.active;
    });
    return columns;
};

export const getMutations = (): MutationTree<GridState> => {
    const mutations: MutationTree<GridState> = {
        setGridInstance(state: GridState, grid: Gikam.component.Grid) {
            state.gridInstance = grid;
        },

        setColumns(state: GridState, columns: GridColumn[]) {
            state.columns = columns;
            state.rawColumns = columns;
        },

        setActiveColumn(state: GridState, column: GridColumnVue) {
            if (state.activeColumn) {
                if (state.activeColumn == column) {
                    return;
                } else {
                    state.activeColumn.active = false;
                }
            }
            state.activeColumn = column;
        },

        setActiveColumnEditorAttr(state: GridState, column: GridColumnVue) {
            state.activeColumnEditorAttrs = getColumnAttributes(column).map(item => {
                if (state.activeColumn) {
                    if (typeof item.value === "object") {
                        item.value = JSON.stringify(item.value);
                    }
                }
                return item;
            });
        },

        setActiveColumnEditorEvents(state: GridState, column: GridColumnVue) {
            state.activeColumnEditorEvents = getColumnEvents(column);
        },

        saveColumns(state: GridState) {
            state.columns = formatterColumns(state.tempColumns as GridColumn[]);
        }
    };

    return getActivatedCompMutations(mutations);
};
