












import { BaseVueComponent, BasePropPanel, Component } from "sunway-vue";

import SelectItem = Gikam.component.SelectItem;

interface Props {
    items: SelectItem[];
    value: string | number;
    target: Node;
}

@Component({
    components: {
        BasePropPanel
    }
})
export default class SelectPicker extends BaseVueComponent<Props> {
    get items() {
        return this.props.items;
    }

    get value() {
        return this.props.value;
    }

    get target() {
        return this.props.target;
    }

    private itemClick(item: SelectItem) {
        this.$emit("itemClick", item);
    }
}
