import { Vuex } from "@/com/sunwayworld/framework/gikam/vue";
import { getState } from "./state/PageDesignState";
import { getMutations } from "./mutations/PageDesignMutations";
import { getActions } from "./actions/PageDesignActions";

/**
 *
 * @description action对应方法
 * @export
 * @enum {number}
 */
export enum PageDesignActions {
    PROCESS_COMP_MASK = "processCompMask",
    PROCESS_GRID_MASK = "processGridMask",
    PROCESS_FORM_MASK = "processFormMask",
    CHANGE_MASK_DATA = "changeMaskData",
    SAVE_FILE = "saveFile",
    SUBMIT_FILE = "submitFile",
    SHOW_LOADING_MASK = "showLoadingMask",
    CLEAN_CODE_EDIT = "cleanCodeEditContent",
    UPDATE_COMP_OPTIONS = "updateCompOptions",
    UPDATE_GRID_COLUMNS = "updateGridColumns",
    UPDATE_FROM_FIELDS = "updateFormFields"
}

/**
 *
 * @description mutations对应方法
 * @export
 * @enum {number}
 */
export enum PageDesignMutations {
    UPDATE_MENU_TREE = "updateMenuTree",
    UPDATE_WORKSPACE = "updateWorkspace",
    CHANGE_MASK_DATA = "changeMaskData",
    CLEAR_MASK_DATA = "clearMaskData",
    UPDATE_MASK_DATA = "updateMaskData",
    SAVE_MASK_DATA = "saveMaskData",
    SET_ACTIVATED_MENU = "setActivatedMenu",
    SET_ACTIVATED_COMP_FILE = "setActivatedCompFile",
    SET_CODE_EDITOR = "setCodeEditor",
    SET_FILE_EDITING = "setFileEditing",
    // 当前正在编辑的遮罩
    SET_EDITING_MASK = "setEditingMask"
}

export default new Vuex.Store({
    state: getState(),
    mutations: getMutations(),
    actions: getActions()
});
