import { ActionTree } from "vuex";
import { GridState, GridColumnVue } from "../../interface/GridInterface";
import { ColumnChangeOption } from "@/com/sunwayworld/components/grid/interface/ColumnAttrEditor";
import { ArrayUtils } from "@/com/sunwayworld/framework/utils/ArrayUtils";

export const getActions = (): ActionTree<GridState, GridState> => {
    const actions: ActionTree<GridState, GridState> = {
        activeColumn({ commit }, activeColumn) {
            commit("setActiveColumn", activeColumn);
            commit("setActiveColumnEditorAttr", activeColumn);
            commit("setActiveColumnEditorEvents", activeColumn);
        },

        updateColumnAttr({ state }, option: ColumnChangeOption) {
            if (state.activeColumn) {
                const column = (state.activeColumn as unknown) as Record<string, string | undefined | null | number>;
                column[option.name] = option.value;
            }
        },

        /**
         * @description 将列编辑的结果更新到grid组件中
         * @param {*} { state }
         */
        updateGridColumns({ state }) {
            state.tempColumns.forEach(column => {
                if (column.active) {
                    delete column.active;
                }
            });

            if (state.gridInstance) {
                state.gridInstance.store.state.columns = state.tempColumns;
            }
        },

        /**
         * @description 新增列
         * @param {*} { state }
         */
        insertColumn({ state }) {
            if (state.activeColumn) {
                const column: GridColumnVue = { title: "新建列", field: "", attribute: "", active: true };
                const index = state.tempColumns.indexOf(state.activeColumn);
                state.tempColumns.splice(index + 1, 0, column);
            }
        },

        moveColumnUp({ state }) {
            if (state.activeColumn) {
                const index = state.tempColumns.indexOf(state.activeColumn);
                if (index === 0) {
                    Gikam.alert("已经处于置顶，无法上移");
                    return;
                }
                ArrayUtils.swap(state.tempColumns, index, index - 1);
            }
        },

        moveColumnDown({ state }) {
            if (state.activeColumn) {
                const index = state.tempColumns.indexOf(state.activeColumn);
                if (index === state.tempColumns.length) {
                    Gikam.alert("已经处于置底，无法下移");
                    return;
                }
                ArrayUtils.swap(state.tempColumns, index, index + 1);
            }
        },

        /**
         * @description 删除列
         * @param {*} { state }
         */
        removeColumn({ state }) {
            if (state.activeColumn) {
                const index = state.tempColumns.indexOf(state.activeColumn);
                state.tempColumns.splice(index, 1);
                state.tempColumns[index > state.tempColumns.length ? index : index - 1].active = true;
            }
        }
    };
    return actions;
};
