import { ActionTree, MutationTree } from "sunway-vue";
import { CompFile } from "@/com/sunwayworld/framework/file/CompFile";

export interface BaseActivatedCompState {
    //页面url地址
    pageUrl?: string;
    //组件所在的js文件内容
    compFileText?: string;
}

export function getActivatedCompState<S extends BaseActivatedCompState>(state: S): S {
    state.compFileText = "";
    state.pageUrl = "";
    return state;
}

export function getActivatedCompMutations<S extends BaseActivatedCompState>(
    mutations: MutationTree<S>
): MutationTree<S> {
    mutations.setPageUrl = (state: S, url: string) => {
        state.pageUrl = url;
    };
    mutations.setCompFileText = (state: S, fileText: string) => {
        state.compFileText = fileText;
    };
    return mutations;
}

export function getActivatedCompAction<S, R, C extends Gikam.component.BaseComp>(
    actions: ActionTree<S, R>,
    comp: C
): ActionTree<S, R> {
    //展示代码文件
    actions.showCompFileText = async ({ commit }) => {
        const pageUrl = comp.$window.history[comp.$window.history.length - 1];
        const compFile = new CompFile(pageUrl, comp.options.id);
        commit("setPageUrl", compFile.pageUrl);
        //commit("setCompFileText", await compFile.getFileText());
    };
    return actions;
}
