



















import { Vue, Component, Prop } from "vue-property-decorator";
import ArrowDownImg from "../img/ArrowDownImg.vue";

@Component({
    components: { ArrowDownImg }
})
export default class Panel extends Vue {
    @Prop({
        type: Boolean,
        default: true
    })
    private canFolded!: boolean;

    @Prop({
        type: Number,
        default: null
    })
    private height!: number;

    @Prop({
        type: String
    })
    title!: string;

    private isExpand = true;

    private toggleHandle(): void {
        this.isExpand = !this.isExpand;
    }
}
