
import { BaseVueComponent, Component, Watch } from "sunway-vue";
import { EditorProps, ValueType } from "./interface/Editor";
@Component
export default class BaseEditor<T extends EditorProps> extends BaseVueComponent<T> {
    protected readonly = Gikam.isEmpty(this.props.readonly) ? false : (this.props.readonly as boolean);
    protected value = this.props.value;
    protected oldValue = this.props.value;
    private isChange = false;

    protected emitChange(value: ValueType, oldValue: ValueType) {
        this.$emit("change", value, oldValue, this.name);
    }

    get name() {
        return this.props.attribute;
    }

    @Watch("props.value")
    watchPropsValue() {
        this.value = this.props.value;
    }
}
