import { MutationTree } from "sunway-vue";
import { PageDesignState, CodeEditor } from "../../interface/PageDesignInterface";
import { PageDesignMutations } from "../pageDesignStore";
import { getGridAttribute, getGridEvent, getGridOther } from "../../../grid/store/getGrid/getGrid";
import { getFormAttribute, getFormEvent } from "../../../form/store/getForm/getForm";
import { AttributeValue } from "../../../grid/interface/ColumnAttrEditor";
import { CompFile } from "@/com/sunwayworld/framework/file/CompFile";
import CompMask from "@/com/sunwayworld/components/compmask/CompMask.vue";

export function getMutations(): MutationTree<PageDesignState> {
    return {
        [PageDesignMutations.UPDATE_MENU_TREE]: (state: PageDesignState, payload: Menu[]) => {
            state.menuTree = payload;
        },

        [PageDesignMutations.UPDATE_WORKSPACE](state: PageDesignState, payload: Workspace) {
            state.workspace = payload;
        },

        [PageDesignMutations.CHANGE_MASK_DATA](state: PageDesignState, comp) {
            if (state.activeId === comp.options.id) {
                return;
            }
            if (comp === state.compData) {
                return;
            }
            state.activeId = comp.options.id;
            state.compData = comp;
            state.tempCompData = Gikam.deepExtend(comp);
            if (comp instanceof Gikam.component.Grid) {
                state.attributes = getGridAttribute(comp.options).map(item => {
                    !item.editorType && (item.editorType = "text");
                    return item;
                });
                state.events = getGridEvent(comp.options);
                state.others = getGridOther(comp.options);
            } else if (comp instanceof Gikam.component.Form) {
                state.attributes = getFormAttribute(comp.options).map(item => {
                    !item.editorType && (item.editorType = "text");
                    return item;
                });
                state.events = getFormEvent(comp.options);
            }
        },

        [PageDesignMutations.CLEAR_MASK_DATA](state: PageDesignState) {
            state.activeId = "";
            state.compData = void 0;
            state.tempCompData = void 0;
            state.attributes = [];
            state.events = [];
            state.others = [];
        },

        updateMaskData(state: PageDesignState, attribute: AttributeValue) {
            const options = state.tempCompData?.options as GeneralObject;
            options[attribute.attribute] = attribute.value;
            state.compData = state.tempCompData;
        },

        //文件保存
        saveFile() {
            Gikam.post(
                Gikam.IFM_CONTEXT + "/secure/core/module/admin/page-configs/action/insert-or-update",
                Gikam.getJsonWrapper(null, ["", [{ menuId: "1", content: "1" }]])
            );
        },

        [PageDesignMutations.SET_ACTIVATED_MENU](state: PageDesignState, menu: Menu) {
            state.activatedMenu = menu;
        },

        //点击组件时
        [PageDesignMutations.SET_ACTIVATED_COMP_FILE](state: PageDesignState, compFile: CompFile) {
            state.activatedCompFile = compFile;
        },

        //代码编辑器
        [PageDesignMutations.SET_CODE_EDITOR](state: PageDesignState, codeEditor: CodeEditor) {
            state.codeEditor = codeEditor;
        },

        [PageDesignMutations.SET_FILE_EDITING](state: PageDesignState, isEditing: boolean) {
            state.fileEditing = isEditing;
        },

        [PageDesignMutations.SET_EDITING_MASK](state: PageDesignState, mask: CompMask) {
            state.editingMask = mask;
        }
    };
}
