
import { Component } from "sunway-vue";
import BaseVueComponent from "@/com/sunwayworld/framework/base/BaseVueComponent.vue";

interface Props {
    color: string;
    width: number | string;
    height: number | string;
}

@Component
export default class BaseSvgImg extends BaseVueComponent<Props> {
    get color() {
        return this.props.color || "#ffffff";
    }

    get width() {
        return this.props.width;
    }

    get height() {
        return this.props.height;
    }
}
