import { getRangeByCompId } from "./getRangeByCompId";

interface ReplaceContent {
    lineNum: number;
    content: string;
}

/**
 * @description 组件定义所在的js文件
 * @export
 * @class CompFile
 */
export class CompFile {
    //业务页面html对应的路径
    pageUrl: string;
    //组件所在的文件地址
    fileUrl = "";
    //组件所在的文件内容
    private text: string | null = null;
    //组件id
    private compId?: string;
    //当前window
    private window: Gikam.component.Window;
    //组件定义开始的行号
    private beginIndex!: number;
    //组件定义结束的行号
    private endIndex!: number;
    //文件的行数组
    private textLines!: string[];

    constructor(pageUrl: string, compId?: string) {
        this.pageUrl = pageUrl;
        this.compId = compId;
        this.window = window.workspace.window;
    }

    private async getFileText() {
        const urls: RegExpMatchArray | null = this.window.htmlText.match(/'\/[\w|/|-]+\.js'/g);
        return await this.getCompFile(urls);
    }

    private async getCompFile(urls: RegExpMatchArray | null) {
        return new Promise<string | null>((resolve, reject) => {
            const getJsFile = (urls: RegExpMatchArray) => {
                if (urls.length > 0) {
                    Gikam.getText(urls[0].replace(/'/g, "")).done((text?: string) => {
                        if (text && text.match(new RegExp(`id : '${this.compId}'`))) {
                            this.fileUrl = urls[0].replace(/'/g, "");
                            resolve(text);
                        } else {
                            urls.shift();
                            getJsFile(urls);
                        }
                    });
                } else {
                    resolve(null);
                }
            };
            urls == null ? reject() : getJsFile(urls);
        });
    }

    private async getPageText(): Promise<string> {
        return new Promise(resolve => {
            Gikam.getText(this.pageUrl).done((pageText: string) => {
                resolve(pageText);
            });
        });
    }

    /**
     * @description 获取组件所在的文件文本
     * @returns {(string | null)}
     * @memberof CompFile
     */
    public getText(): string | null {
        return this.text;
    }

    /**
     * @description 从注入的html的中获取修改的文件内容
     * @memberof CompFile
     */
    public initInnerHtmlText() {
        this.window?.jsFileManager.forEach((content, url) => {
            if (content.match(new RegExp(`id : '${this.compId}'`))) {
                this.fileUrl = url;
                this.text = content;
            }
        });
    }

    /**
     * @description 初始化组件
     * @memberof CompFile
     */
    public async init() {
        this.text = await this.getFileText();
        if (!this.text) {
            this.initInnerHtmlText();
        }
        if (this.compId && this.text) {
            const position = getRangeByCompId(this.compId, this.text);
            this.beginIndex = position.beginIndex;
            this.endIndex = position.endIndex;
            this.textLines = this.text.split(/\n/);
        }
    }

    /**
     * @description 替换组件属性，不包含事件
     * @param {string} option
     * @param {string} result
     * @memberof CompFile
     */
    public replaceCompOption(option: string, result: string): ReplaceContent {
        let replaceLineNum = 0;
        const replaceLineText = `${option} : ${result}`;
        for (let i = this.beginIndex; i < this.endIndex; i++) {
            const lineText = this.textLines[i];
            if (lineText.replace(/\s/g, "").includes(option + ":")) {
                this.textLines[i] = replaceLineText + ",";
                replaceLineNum = i;
                break;
            }
        }
        return {
            lineNum: replaceLineNum,
            content: replaceLineText
        };
    }
}
