







import { Component } from "sunway-vue";
import BaseEditor from "./BaseEditor.vue";
import { EditorProps } from "./interface/Editor";

@Component
export default class NumberInputEditor extends BaseEditor<EditorProps> {
    changeHandle(event: Event) {
        this.value = (event.target as HTMLInputElement).value;
        this.$emit("change", {
            value: this.value,
            oldValue: this.oldValue,
            name: this.name,
            param: this.props
        });
        this.oldValue = this.value;
    }
}
