import { FormState } from "../../interface/FormInterface";

const formatterOptions = (options: Gikam.component.FormOptions): Gikam.component.FormOptions => {
    options.panels.forEach(panel => {
        panel.fields.forEach((field, index) => {
            field.active = index === 0 ? true : false;
        });
    });
    return options;
};

export const getState = (form: Gikam.component.Form): FormState => {
    const tempOptions: Gikam.component.FormOptions = Gikam.deepExtend(form.options);
    return {
        formInstance: form,
        options: form.options,
        tempOptions: formatterOptions(Gikam.deepExtend(form.options)),
        panels: tempOptions.panels,
        activeField: void 0,
        activeFieldEditorAttrs: void 0,
        activeFieldEditorEvents: void 0
    };
};
