import FullScreenLoading from "@/com/sunwayworld/components/loading/FullScreenLoading.vue";
import { Vue } from "sunway-vue";

export class MaskUtils {
    static fullScreenMaskViewModel?: Vue;

    public static async showFullScreenMask(message = "数据请求中，请稍候") {
        const vueModel = new Vue({
            el: Gikam.createDom("div", document.body),
            components: {
                FullScreenLoading
            },
            render(h) {
                return h("full-screen-loading", {
                    props: { message }
                });
            }
        });
        MaskUtils.fullScreenMaskViewModel = vueModel;
        return new Promise(resolve => {
            vueModel.$nextTick(() => {
                resolve();
            });
        });
    }

    public static closeFullScreenMask(timeout = 0) {
        setTimeout(() => {
            if (MaskUtils.fullScreenMaskViewModel) {
                Gikam.removeDom(MaskUtils.fullScreenMaskViewModel.$el);
                MaskUtils.fullScreenMaskViewModel.$destroy();
                MaskUtils.fullScreenMaskViewModel = undefined;
            }
        }, timeout);
    }
}
