import SelectItem = Gikam.component.SelectItem;

function getYesNo(): SelectItem[] {
    return [
        {
            value: true,
            text: "是"
        },
        {
            value: false,
            text: "否"
        }
    ];
}

function getAlignItems(): SelectItem[] {
    return [
        {
            value: "left",
            text: "左对齐"
        },
        {
            value: "center",
            text: "居中对齐"
        },
        {
            value: "right",
            text: "右对齐"
        }
    ];
}

export class SelectUtils {
    static readonly yesNo = getYesNo();
    static readonly align = getAlignItems();
}
