import { PageDesign } from "./components/main/ts/PageDesign";
import Vue from "vue";
import vuescroll from "vuescroll";
import animated from "animate.css";

Vue.use(animated);
Gikam.component.FrontI18N.init(Gikam.local);

Vue.use(vuescroll, {
    ops: {
        bar: {
            showDelay: 500,
            onlyShowBarOnScroll: false,
            keepShow: false,
            background: "#c1c1c1",
            opacity: 0.5,
            hoverStyle: false,
            specifyBorderRadius: false,
            minSize: false,
            size: "6px",
            disable: false
        }
    },
    name: "scroll"
});

window.PageDesign = PageDesign;
