import { ActionTree } from "vuex";
import { FormState, FieldChangeOption, FormFieldVue } from "../../interface/FormInterface";
import { ArrayUtils } from "@/com/sunwayworld/framework/utils/ArrayUtils";

export const getActions = (): ActionTree<FormState, FormState> => {
    return {
        activeField({ commit }, activeField) {
            commit("setActiveField", activeField);
            commit("setActiveFieldEditorAttr", activeField);
            commit("setActiveFieldEditorEvents", activeField);
        },

        updateFieldAttr({ state }, option: FieldChangeOption) {
            if (state.activeField) {
                const field = (state.activeField as unknown) as Record<string, string | undefined | null | number>;
                field[option.name] = option.value;
            }
        },

        /**
         * @description 将列编辑的结果更新到Form组件中
         * @param {*} { state }
         */
        updateFormFields({ state }) {
            state.tempOptions?.panels.forEach(panel => {
                panel.fields.forEach(field => {
                    if (field.active) {
                        delete field.active;
                    }
                });
            });
            if (state.formInstance) {
                state.formInstance.options.panels = state.tempOptions?.panels;
            }
        },

        insertField({ state }) {
            if (state.activeField) {
                const fields = state.tempOptions.panels[0].fields;
                const column: FormFieldVue = { title: "新建字段", field: "newField", attribute: "", active: true };
                const index = fields.indexOf(state.activeField);
                fields.splice(index + 1, 0, column);
            }
        },

        moveFieldUp({ state }) {
            if (state.activeField) {
                const fields = state.tempOptions.panels[0].fields;
                const index = fields.indexOf(state.activeField);
                if (index === 0) {
                    Gikam.alert("已经处于置顶，无法上移");
                    return;
                }
                ArrayUtils.swap(fields, index, index - 1);
            }
        },

        moveFieldDown({ state }) {
            if (state.activeField) {
                const fields = state.tempOptions.panels[0].fields;
                const index = fields.indexOf(state.activeField);
                if (index === fields.length) {
                    Gikam.alert("已经处于置底，无法下移");
                    return;
                }
                ArrayUtils.swap(fields, index, index + 1);
            }
        },

        /**
         * @description 删除列
         * @param {*} { state }
         */
        removeField({ state, dispatch }) {
            if (state.activeField) {
                const fields = state.tempOptions.panels[0].fields;
                const index = fields.indexOf(state.activeField);
                fields.splice(index, 1);
                const newIndex = index > fields.length - 1 ? fields.length - 1 : index;
                const nextField = fields[newIndex];
                nextField.active = true;
                dispatch("activeField", nextField);
            }
        }
    };
};
