Gikam.trimBlank = text => {
    return text ? text.replace(/\s/g, "") : "";
};

/**
 *
 * @description 格式化字符串，去掉空格和所有单引号和双引号
 * @param {string} text
 * @returns
 */
function keepAvailableText(text: string): string {
    return Gikam.trimBlank(text).replace(/'|"/g, "");
}

interface BlockPosition {
    beginIndex: number;
    endIndex: number;
}

function getReplaceIndex(lines: string[], positionText: string): BlockPosition {
    let beginIndex = 0;
    let endIndex = 0;
    let positionIndex = 0;
    //标识符所在行
    for (let i = 0; i < lines.length; i++) {
        if (keepAvailableText(lines[i]).includes(keepAvailableText(positionText))) {
            positionIndex = i;
            break;
        }
    }
    //开始行
    for (let i = positionIndex; i > -1; i--) {
        if (keepAvailableText(lines[i]).includes("return{")) {
            beginIndex = i;
            break;
        }
    }
    let willCloseNumber = 0;
    //结束行
    for (let i = beginIndex; i < lines.length; i++) {
        const line = lines[i];
        const matchLeft = line.match(/{/g);
        const matchRight = line.match(/}/g);
        willCloseNumber += (matchLeft ? matchLeft.length : 0) - (matchRight ? matchRight.length : 0);
        if (willCloseNumber == 0) {
            endIndex = i;
            break;
        }
    }
    return { beginIndex, endIndex };
}

export function getRangeByCompId(id: string, fileText: string): BlockPosition {
    const lines = fileText.split(/\n/);
    return getReplaceIndex(lines, `id:'${id}'`);
}
