
import CompMask from "@/com/sunwayworld/components/compmask/CompMask.vue";
import { Component, Vue, Store } from "sunway-vue";
import { getStore } from "@/com/sunwayworld/components/grid/store/gridStore";
import { GridState } from "../interface/GridInterface";

@Component
export default class GridMask extends CompMask {
    private store: Store<GridState> | null = null;

    editColumns() {
        this.store = getStore(this.comp as Gikam.component.Grid);
        // eslint-disable-next-line @typescript-eslint/no-this-alias
        const _this = this;
        new Vue({
            el: Gikam.createDom("div", document.body),
            store: this.store,
            components: {
                ColumnsDesginBox: () => import("@/com/sunwayworld/components/grid/columns/ColumnsDesignBox.vue")
            },
            render(this, h) {
                return h("ColumnsDesginBox", {
                    on: {
                        confirmUpdateColumns(grid: Gikam.component.Grid) {
                            _this.$emit("updateGridColumns", grid);
                        }
                    }
                });
            },
            mounted() {
                this.$store.dispatch("showCompFileText");
            }
        });
    }

    public modifyCompObjectAttr(attr: string) {
        if (attr === "columns") {
            this.editColumns();
        }
    }
}
