import SelectItem = Gikam.component.SelectItem;

type ValueType = string | number | null | undefined;

export interface FormState {
    formInstance?: Gikam.component.Form;
    options?: Gikam.component.FormOptions;
    panels: Gikam.component.FormPanel[];
    tempOptions: Gikam.component.FormOptions;
    activeField?: FormFieldVue;
    activeFieldEditorAttrs?: Array<FieldEditor | FormAttribute>;
    activeFieldEditorEvents?: Array<FieldEvent | FormEvent>;
}

export interface FormFieldVue extends FormField {
    active?: boolean;
}

export interface FormAttribute {
    // 编辑属性显示名称
    title: string;
    // 对应属性
    attribute: string;
    // 当前值
    value?: string | boolean | number | string[] | number[];
    // 编辑器类型
    editorType?: string;
    titleWidthAuto?: boolean;
    service?: string;
    autoSave?: boolean;
    id?: string;
    titleAlign?: string;
    titleWidth?: number;
}

export interface FormEvent {
    attribute: string;
    value?: string | boolean | number | string[] | number[];
    onLoadSuccess?: string;
    onAfterChoose?: string;
    onRendered?: string;
    onInserted?: string;
    onUpdated?: string;
    onBeforeUpdate?: string;
}

export interface FormField extends FieldEvent {
    value?: string;
    attribute: string;
    title: string;
    field: string;
    type?: string;
    editor?: boolean;
    category?: string;
    items?: SelectItem[];
}

export interface FieldEditor {
    // 编辑属性显示名称
    title: string;
    // 对应属性
    attribute: string;
    // 当前值
    value?: string | boolean | number | SelectItem[];
    // 编辑器类型
    editorType?: string;
    //是否只读
    readonly?: boolean;
    // 在year, time，date, dateTime,choose, Cron中是否可在输入框手动输入
    editable?: boolean;

    //下拉框属性
    //数据源
    items?: SelectItem[];
    //下拉框是否支持多选
    multiple?: boolean;
    //业务类型，自己定义，可以从*-select-config.js文件中关联后台查询
    category?: string;
    //参数为对象类型，数据库中配置的作为查询条件的参数
    params?: object;
    //下拉菜单第一个元素是否为空
    firstBlank?: boolean;
    //当没有值的时候，默认展示的提示 信息
    placeholder?: string;
    //选择的下拉框第几项
    selectedIndex?: number;
    //下拉框是为有筛选框
    search?: boolean;

    //number属性
    hasArrow?: boolean;
    //是否为整数
    isInteger?: boolean;
    //取值范围 （支持开闭区间）
    range?: string | boolean;

    //choose属性
    //允许更新的字段
    targetFields?: string[] | ChooseField[];
    //跳转的页面 ,数据是单选框
    single?: boolean;
    //选择框中有值时鼠标悬浮会有X号显示用来清空框中数据
    cleanable?: boolean;

    //Date/DateTime属性
    //是否可以选择时分秒
    selectTime?: boolean;
    //界定日期选择的范围
    dateRange?: string[];

    //textarea属性高度
    height?: number;

    //cron属性 -pageReadonly页面配置，是否只读
    pageReadonly?: boolean;
}

export interface FieldEvent {
    attribute: string;
    value?: string | boolean | number | string[] | number[];
    onClick?: string;
    onChange?: string;
    onBlur?: string;
    onKeyDown?: string;
    onInput?: string;
    onAllClick?: string;
    // text字段事件，返回包含样式的对象
    textStyleFormatter?: string;
    // SimpleCheckbox字段方法，返回包含样式的对象
    styleFormatter?: string;
    // choose字段事件, 选择页弹出之前做的操作
    onBeforeChoose?: string;
    // choose字段事件, 选择数据之后所做的操作
    onAfterChoose?: string;
    // 格式化问文本（field, value）
    formatter?: string;
    // 字段事件（field, value, rowIndex），当点击输入框中删除符号清空字段值时触发的操作
    onClean?: string;
    // 字段事件 如果有onChoose 事件就点击右侧鼠标就只执行传入的事件
    onChoose?: string;
    onBeforeSelect?: string;
}

export enum FieldType {
    SELECT = "select",
    TEXT = "text",
    CHOOSE = "choose",
    NUMBER = "number",
    DATE = "date",
    DATE_TIME = "dateTime",
    TIME = "time",
    YEAR = "year",
    INSERTABL_ESELECT = "inserTableSelect",
    CHECKBOX = "checkbox",
    SIMPLE_CHECKBOX = "simpleCheckbox",
    TEXTAREA = "textarea",
    LINK = "link",
    IMAGE = "image",
    CKEDITOR = "ckeditor",
    SCRIPT_FIELD = "scriptField",
    COMBO_BOX = "comboBox",
    CRON = "cron",
    RICHTEXT = "richText",
    RICHTEXT_CHOOSE = "richTextChoose"
}

interface ChooseField {
    [propName: string]: string;
}

export type SelectEditor = FieldEditor & {
    category: string;
};

export interface AttributeValue {
    value: string;
    oldValue: string;
    attribute: string;
}

export interface FieldChangeOption {
    name: string;
    value: ValueType;
    oldValue: ValueType;
}
