






import { Component, BaseVueComponent, Watch, Mutation } from "sunway-vue";

interface Props {
    comp: Gikam.component.BaseComp;
    activeId: string;
}

@Component
export default class CompMask extends BaseVueComponent<Props> {
    static activeMask: CompMask;

    protected active = false;

    protected timer = 0;

    protected editingAttr: string | null = null;

    @Mutation
    private setEditingMask!: (mask: CompMask) => void;

    @Mutation("changeMaskData")
    private setEditingComp!: (comp: Gikam.component.BaseComp) => void;

    @Watch("activeId")
    changeActiveId(val: string) {
        if (this.comp.options.id === val) {
            this.active = true;
        } else {
            this.active = false;
        }
    }

    get comp() {
        return this.props.comp;
    }

    get activeId() {
        return this.props.activeId;
    }

    showMainSetting() {
        clearTimeout(this.timer);
        this.setEditingMask(this);
        this.setEditingComp(this.comp);
    }

    // 修改组件对象类型的属性
    public modifyCompObjectAttr(attr: string) {
        this.editingAttr = attr;
    }
}
