import { GridState } from "../interface/GridInterface";
import { Vuex } from "@/com/sunwayworld/framework/gikam/vue";
import { getMutations } from "./mutations/mutations";
import { getActions } from "./actions/actions";
import { getState } from "./state/state";
import { getGetters } from "./getter/getters";

export const getStore = (grid: Gikam.component.Grid) => {
    return new Vuex.Store<GridState>({
        state: getState(grid),
        mutations: getMutations(),
        actions: getActions(),
        getters: getGetters()
    });
};
