import { ActionTree, Store } from "vuex";
import Vue from "vue";
import {
    PageDesignState,
    EditorChangeEmitParam
} from "@/com/sunwayworld/components/main/interface/PageDesignInterface";
import GridMask from "@/com/sunwayworld/components/grid/mask/GridMask.vue";
import FormMask from "@/com/sunwayworld/components/form/mask/FormMask.vue";
import { PageDesignActions, PageDesignMutations } from "../pageDesignStore";
import { MaskUtils } from "@/com/sunwayworld/framework/utils/MaskUtils";

const baseUrl = Gikam.IFM_CONTEXT + "/secure/core/module/admin/page-drafts";

export function getActions(): ActionTree<PageDesignState, PageDesignState> {
    return {
        [PageDesignActions.PROCESS_COMP_MASK]: ({ commit, state, dispatch }, store: Store<PageDesignState>) => {
            commit(PageDesignMutations.CLEAR_MASK_DATA);
            state.workspace?.window.onReady(() => {
                setTimeout(() => {
                    Gikam.each(
                        state.workspace?.window.$compStore.Grid as Gikam.component.Grid[],
                        (index: number, grid: Gikam.component.Grid) => {
                            new Vue({
                                el: Gikam.createDom("div", grid.model.$el as HTMLElement),
                                store,
                                render(h) {
                                    return h(GridMask, {
                                        props: {
                                            props: {
                                                comp: grid,
                                                activeId: state.activeId
                                            }
                                        },
                                        on: {
                                            updateGridColumns(grid: Gikam.component.Grid) {
                                                dispatch(PageDesignActions.UPDATE_GRID_COLUMNS, grid);
                                            }
                                        }
                                    });
                                }
                            });
                        }
                    );
                    Gikam.each(
                        state.workspace?.window.$compStore.Form as Gikam.component.Form[],
                        (index: number, form: Gikam.component.Form) => {
                            new Vue({
                                el: Gikam.createDom("div", form.model.$el as HTMLElement),
                                store,
                                render(h) {
                                    return h(FormMask, {
                                        props: {
                                            props: {
                                                comp: form,
                                                activeId: state.activeId
                                            }
                                        },
                                        on: {
                                            updateFormFields(form: Gikam.component.FormPanel) {
                                                dispatch(PageDesignActions.UPDATE_FROM_FIELDS, form);
                                            }
                                        }
                                    });
                                }
                            });
                        }
                    );
                }, 800);
            });
        },

        [PageDesignActions.SAVE_FILE]({ state, commit }, showTip = true) {
            return new Promise(async resolve => {
                if (!state.activatedMenu || !state.activatedCompFile) {
                    return;
                }

                await MaskUtils.showFullScreenMask();
                Gikam.post(
                    baseUrl + "/action/insert-or-update",
                    Gikam.getJsonWrapper({
                        menuId: state.activatedMenu.id,
                        content: state.codeEditor?.getValue(),
                        jsUri: state.activatedCompFile.fileUrl,
                        requestUri: state.activatedMenu.href
                    })
                )
                    .done(id => {
                        resolve(id);
                        commit(PageDesignMutations.SET_FILE_EDITING, false);
                        if (showTip) {
                            Gikam.toast("保存成功", undefined, "middle");
                        }
                    })
                    .always(() => {
                        MaskUtils.closeFullScreenMask();
                    });
            });
        },

        async [PageDesignActions.SUBMIT_FILE]({ state, dispatch }) {
            if (!state.activatedMenu || !state.activatedCompFile) {
                return;
            }
            const id = await dispatch(PageDesignActions.SAVE_FILE, false);
            Gikam.put(baseUrl + `/${id}/action/release`).done(() => {
                Gikam.toast("提交成功", undefined, "middle");
            });
        },

        [PageDesignActions.CLEAN_CODE_EDIT]({ state }) {
            state.codeEditor?.setValue("");
        },

        /**
         * @description 更新组件配置参数
         * @param {*} { state }
         * @param {EditorChangeEmitParam} compOption
         * @returns
         */
        [PageDesignActions.UPDATE_COMP_OPTIONS]({ state }, compOption: EditorChangeEmitParam) {
            if (!state.activatedCompFile) {
                return;
            }
            const replacePosition = state.activatedCompFile.replaceCompOption(compOption.name, compOption.value);
            if (state.codeEditor) {
                state.codeEditor.replaceRange(
                    replacePosition.content + ",\n",
                    { line: replacePosition.lineNum, ch: 0 },
                    { line: replacePosition.lineNum + 1, ch: 0 }
                );
            }
        },

        async [PageDesignActions.UPDATE_GRID_COLUMNS]({ dispatch }, grid: Gikam.component.Grid) {
            const columns = Gikam.deepExtend<Gikam.component.GridColumn[]>(grid.store.state.columns);
            columns.forEach(item => {
                if (item.type === "select" && item.category && item.items) {
                    delete item.items;
                }
            });
            await dispatch(PageDesignActions.UPDATE_COMP_OPTIONS, {
                name: "columns",
                value: Gikam.parseObjectToString(columns).replace(/\n|\s/g, " ")
            });
        },

        async [PageDesignActions.UPDATE_FROM_FIELDS]({ dispatch }, form: Gikam.component.Form) {
            const panels = Gikam.deepExtend<Gikam.component.FormPanel[]>(form.options.panels);
            panels.forEach(panel => {
                panel.fields.forEach(item => {
                    if (item.type === "select" && item.category && item.items) {
                        delete item.items;
                    }
                });
            });
            await dispatch(PageDesignActions.UPDATE_COMP_OPTIONS, {
                name: "fields",
                value: Gikam.parseObjectToString(panels[0].fields).replace(/\n|\s/g, " ")
            });
        }
    };
}
