






import { BaseVueComponent, Component } from "sunway-vue";

interface Props {
    target: Node;
}

interface Position {
    left: number;
    top: number;
    width: number;
    height: number;
}

let panelInstance: BasePropPanle | null = null;

window.onmousedown = () => {
    if (panelInstance) {
        Gikam.removeDom(panelInstance.$el);
        panelInstance.$destroy();
    }
};

@Component
export default class BasePropPanle extends BaseVueComponent<Props> {
    getPosition(): Position {
        const targetDom = (this.props.target as HTMLElement).getBoundingClientRect();
        return {
            left: targetDom.left,
            top: targetDom.top,
            width: targetDom.width,
            height: targetDom.height
        };
    }

    mounted() {
        this.$nextTick(() => {
            const { width, left, top, height } = this.getPosition();
            const dom = this.$el as HTMLElement;
            dom.style.width = width + "px";
            dom.style.left = left + "px";
            dom.style.top = top + height + 1 + "px";
            document.body.appendChild(this.$el);
        });
    }

    beforeCreate() {
        if (panelInstance) {
            Gikam.removeDom(panelInstance.$el);
            panelInstance.$destroy();
        }
        panelInstance = this;
    }

    destroyed() {
        panelInstance = null;
        this.$emit("destroyed");
    }
}
