

























import { Component, Prop, State, Action, BaseVueComponent, Store, Mutation } from "sunway-vue";
import { PageDesignActions, PageDesignMutations } from "@/com/sunwayworld/components/main/store/pageDesignStore";
import { Constant } from "@/com/sunwayworld/framework/constant/Constant";
import ArrowRightSolidImg from "../img/ArrowRightSolidImg.vue";
import ArrowRightHollowImg from "../img/ArrowRightHollowImg.vue";
import { PageDesignState as DesignStateInterface } from "@/com/sunwayworld/components/main/interface/PageDesignInterface";

@Component({
    components: {
        TreeNodeList: () => import("./TreeNodeList.vue"),
        ArrowRightSolidImg,
        ArrowRightHollowImg
    }
})
export default class extends BaseVueComponent<object> {
    @Prop({
        required: true
    })
    private node!: Menu;

    @Prop()
    private level!: number;

    get text(): string {
        return this.node.text;
    }

    get expand(): boolean {
        return this.node.expand || false;
    }

    @Action(PageDesignActions.PROCESS_COMP_MASK)
    private processCompMask!: (store: Store<DesignStateInterface>) => void;

    @Mutation(PageDesignMutations.SET_ACTIVATED_MENU)
    private setActivatedMenu!: (menu: Menu) => void;

    @Action(PageDesignActions.CLEAN_CODE_EDIT)
    private cleanCodeEditContent!: () => void;

    @State
    private workspace!: Workspace;

    private clickHandle(): void {
        this.$set(this.node, "expand", !this.node.expand);
        if (Gikam.isNotEmpty(this.node.href)) {
            this.cleanCodeEditContent();
            this.workspace.window.isEdit = true;
            this.workspace.window.options.objectId = this.node.id;
            this.workspace.window.load(Constant.IFM_CONTEXT + this.node.href);
            this.processCompMask(this.$store);
            this.setActivatedMenu(this.node);
        }
    }
}
