import { FormField } from "../../interface/FormInterface";
import { FieldEvent, FieldType } from "../../interface/FormInterface";

// text事件
const getTextEvents = (field?: FormField): FieldEvent[] => {
    return [
        {
            value: field?.formatter?.toString() || '',
            attribute: "onChange"
        },
        {
            value: field?.formatter?.toString() || '',
            attribute: "onKeyDown"
        },
        {
            value: field?.formatter?.toString() || '',
            attribute: "onInput"
        },
        {
            value: field?.formatter?.toString() || '',
            attribute: "textStyleFormatter"
        }
    ];
};

// select/RichText/insertableSelect/number/DateTime/Textarea/Ckeditor/ScriptField/ComboBox/time/year事件
const getCommonEvents = (field?: FormField): FieldEvent[] => {
    return [
        {
            value: field?.formatter?.toString() || '',
            attribute: "onChange"
        }
    ];
};

// checkbox事件
const getCheckboxFieldEvents = (field?: FormField): FieldEvent[] => {
    return [
        {
            value: field?.formatter?.toString() || '',
            attribute: "onChange"
        },
        {
            value: field?.formatter?.toString() || '',
            attribute: "onAllClick"
        },
        {
            value: field?.formatter?.toString() || '',
            attribute: "onClick"
        }
    ];
};

// data事件
const getDataFieldEvents = (field?: FormField): FieldEvent[] => {
    return [
        {
            value: field?.formatter?.toString() || '',
            attribute: "onChange"
        },
        {
            value: field?.formatter?.toString() || '',
            attribute: "onBeforeSelect"
        }
    ];
};

// RichTextChoose事件
const getRichTextChooseFieldEvents = (field?: FormField): FieldEvent[] => {
    return [
        {
            value: field?.formatter?.toString() || '',
            attribute: "onChange"
        },
        {
            value: field?.formatter?.toString() || '',
            attribute: "onBeforeChoose"
        },
        {
            value: field?.formatter?.toString() || '',
            attribute: "onAfterChoose"
        }
    ];
};

// choose事件
const getChooseFieldEvents = (field?: FormField): FieldEvent[] => {
    return getRichTextChooseFieldEvents().concat([
        {
            value: field?.formatter?.toString() || '',
            attribute: "formatter"
        },
        {
            value: field?.formatter?.toString() || '',
            attribute: "onClean"
        },
        {
            value: field?.formatter?.toString() || '',
            attribute: "onChoose"
        }
    ]);
};

export const getFieldEvents = (field?: FormField): FieldEvent[] => {
    if (!field) {
        return getTextEvents(field);
    }
    if (!field.type) {
        return getTextEvents(field);
    }
    switch (field.type) {
        case FieldType.CHECKBOX: {
            return getCheckboxFieldEvents(field);
        }
        case FieldType.DATE: {
            return getDataFieldEvents(field);
        }
        case FieldType.RICHTEXT_CHOOSE: {
            return getRichTextChooseFieldEvents(field);
        }
        case FieldType.CHOOSE: {
            return getChooseFieldEvents(field);
        }
        default:
            return getCommonEvents(field);
    }
};
