import { FormField, FieldEditor, FieldType } from "../../interface/FormInterface";

//获取通用字段属性
const getCommonAttrs = (field?: FormField): FieldEditor[] => {
    return [
        {
            title: "字段",
            attribute: "field",
            editorType: "text",
            value: field?.field
        },
        {
            title: "字段名称",
            attribute: "title",
            editorType: "text",
            value: field ? Gikam.propI18N(field.title) : ""
        }
    ];
};

//获取下拉框编辑时的属性
const getSelectAttrs = (field: FormField): FieldEditor[] => {
    return getCommonAttrs(field).concat([
        {
            title: "数据源",
            attribute: "category",
            editorType: "select",
            value: field.category,
            items: field.items
        }
    ]);
};

// 数字类型
const getNumberFieldAttrs = (field: FormField): FieldEditor[] => {
    return getCommonAttrs(field).concat([
        {
            title: "是否显示箭头",
            attribute: "hasArrow",
            editorType: "select",
            value: field.category,
            items: field.items
        },
        {
            title: "是否为整数",
            attribute: "isInteger",
            editorType: "select",
            value: field.category,
            items: field.items
        },
        {
            title: "取值范围",
            attribute: "range",
            editorType: "text",
            value: field.category
        }
    ]);
};

// choose类型
const getChooseFieldAttrs = (field: FormField): FieldEditor[] => {
    return getCommonAttrs(field).concat([
        {
            title: "是否单选",
            attribute: "single",
            editorType: "select",
            value: field.category
        },
        {
            title: "是否可清除",
            attribute: "cleanable",
            editorType: "select",
            value: field.category
        }
    ]);
};

// dateTime\year类型
const getDateTimeFieldAttrs = (field: FormField): FieldEditor[] => {
    return getCommonAttrs(field).concat([
        {
            title: "是否可输入",
            attribute: "editable",
            editorType: "select",
            value: field.category
        },
        {
            title: "可选日期范围",
            attribute: "dateRange",
            editorType: "text",
            value: field.category
        }
    ]);
};

// date类型
const getDateFieldAttrs = (field: FormField): FieldEditor[] => {
    return getDateTimeFieldAttrs(field).concat([
        {
            title: "是否选择时分秒",
            attribute: "selectTime",
            editorType: "select",
            value: field.category
        }
    ]);
};

export const getFieldAttributes = (field?: FormField): FieldEditor[] => {
    if (!field) {
        return getCommonAttrs(field);
    }
    switch (field.type) {
        case FieldType.SELECT: {
            return getSelectAttrs(field);
        }
        case FieldType.NUMBER: {
            return getNumberFieldAttrs(field);
        }
        case FieldType.CHOOSE: {
            return getChooseFieldAttrs(field);
        }
        case FieldType.DATE: {
            return getDateFieldAttrs(field);
        }
        case FieldType.DATE_TIME:
        case FieldType.YEAR: {
            return getDateTimeFieldAttrs(field);
        }
        default: {
            return getCommonAttrs(field);
        }
    }
};
