/* eslint-disable @typescript-eslint/no-explicit-any */
export class ObjectUtils {
    static deepClone<T>(target?: T | T[]): T | undefined {
        if (!target) {
            return;
        }
        return JSON.parse(JSON.stringify(target));
    }

    static isString(target: any): boolean {
        return typeof target === "string";
    }

    static isBoolean(target: any): boolean {
        return typeof target === "boolean";
    }

    static isFunction(target: any): boolean {
        return typeof target === "function";
    }

    static isEmpty(target: any): boolean {
        if (target == null) {
            return true;
        }
        if (ObjectUtils.isString(target) && target === "") {
            return true;
        }
        if (Array.isArray(target)) {
            return target.length === 0;
        }
        return false;
    }

    static isNotEmpty(target: any) {
        return !ObjectUtils.isEmpty(target);
    }

    static trigger(target: any, methodName: keyof GeneralObject, scope?: any, ...args: any[]): any | undefined {
        if (!target[methodName]) {
            return;
        }
        if (!ObjectUtils.isFunction(target[methodName])) {
            return;
        }
        return (target[methodName] as Function).apply(scope, args);
    }

    static getFinalValue(value: any, defaultValue: any): boolean {
        return ObjectUtils.isNotEmpty(value) ? value : defaultValue;
    }
}
