






import { Vue, Component, Prop } from "vue-property-decorator";
import TreeNode from "./TreeNode.vue";

@Component({
    name: "TreeNodeList",
    components: { TreeNode }
})
export default class TreeNodeList extends Vue {
    @Prop({
        type: Array,
        default: []
    })
    nodeList!: Array<Record<string, any>>;

    @Prop({
        type: Number,
        default: 1
    })
    level!: number;
}
