





































import { Component, Vue } from "sunway-vue";
import DesignHeader from "./header/DesignHeader.vue";
import MenuTreePanel from "./navigation/MenuTreePanel.vue";
import WindowTreePanel from "./navigation/window/WindowTreePanel.vue";
import MainSetting from "./setting/MainSetting.vue";

@Component({
    components: {
        DesignHeader,
        MenuTreePanel,
        WindowTreePanel,
        MainSetting,
        CodeEditPanel: () => import("../../codeEditPanel/CodeEditPanel.vue")
    }
})
export default class App extends Vue {
    $refs!: {
        nav: HTMLHtmlElement;
        view: HTMLHtmlElement;
        setting: HTMLHtmlElement;
        code: HTMLHtmlElement;
    };
    private initX = 0;
    private initY = 0;
    private direction = "";
    private westWidth = document.body.clientWidth * 0.15;
    private eastWidth = document.body.clientWidth * 0.2;
    private codeHeight = document.body.clientHeight * 0.15;
    private centerWidth = 0;
    private viewHeight = 0;
    private resizing = false;

    private dragDown(e: Gikam.DomEvent, direction: string): void {
        this.initX = e.pageX;
        this.initY = e.pageY;
        this.direction = direction;
        this.resizing = true;
        document.addEventListener("mousemove", this.dragMove, false);
        document.addEventListener("mouseup", this.dragUp, false);
    }

    // eslint-disable-next-line complexity
    private dragMove(e: Gikam.DomEvent): void {
        this.centerWidth = this.$refs.view.offsetWidth;
        let distance: number;
        if (this.direction === "west") {
            distance = e.pageX - this.initX;
            if (Math.abs(distance) < 3) return;
            if (distance > 0 && this.centerWidth < 100) return;
            if (distance < 0 && this.westWidth < 100) return;
            this.westWidth = this.westWidth + distance;
            this.westWidth < 100 && (this.westWidth = 100);
        } else if (this.direction === "east") {
            distance = e.pageX - this.initX;
            if (Math.abs(distance) < 3) return;
            if (distance > 0 && this.eastWidth < 100) return;
            if (distance < 0 && this.centerWidth < 100) return;
            this.eastWidth = this.eastWidth - distance;
            this.eastWidth < 100 && (this.eastWidth = 100);
        } else if (this.direction === "north") {
            this.viewHeight = this.$refs.view.offsetHeight;
            distance = e.pageY - this.initY;
            if (Math.abs(distance) < 3) return;
            if (distance > 0 && this.codeHeight < 100) return;
            if (distance < 0 && this.viewHeight < 100) return;
            this.codeHeight = this.codeHeight - distance;
            this.codeHeight < 100 && (this.codeHeight = 100);
        }
        this.initX = e.pageX;
        this.initY = e.pageY;
    }

    private dragUp(): void {
        this.initX = 0;
        this.initY = 0;
        this.direction = "";
        this.resizing = false;
        document.removeEventListener("mousemove", this.dragMove, false);
        document.removeEventListener("mouseup", this.dragUp, false);
    }
}
