






















































import { Vue, Component, State, Mutation, Action } from "sunway-vue";
import Panel from "../panel/Panel.vue";
import TextEditor from "@/com/sunwayworld/components/editor/TextEditor.vue";
import NumberEditor from "@/com/sunwayworld/components/editor/NumberEditor.vue";
import ChooseEditor from "@/com/sunwayworld/components/editor/ChooseEditor.vue";
import SelectEditor from "@/com/sunwayworld/components/editor/select/SelectEditor.vue";
import ObjectEditor from "@/com/sunwayworld/components/editor/ObjectEditor.vue";
import { GridOther, GridEvent, GridAttribute } from "../../../grid/interface/GridInterface";
import { PageDesignActions } from "../../store/pageDesignStore";
import { EditorChangeEmitParam } from "../../interface/PageDesignInterface";
import CompMask from "@/com/sunwayworld/components/compmask/CompMask.vue";

type ValueType = string | number | null | undefined;

@Component({
    components: {
        Panel,
        TextEditor,
        NumberEditor,
        ChooseEditor,
        SelectEditor,
        ObjectEditor
    }
})
export default class MainSetting extends Vue {
    @State
    compData!: Gikam.component.BaseComp;

    @State
    private others!: GridOther[];

    @State
    private events!: GridEvent[];

    @State
    private editingMask!: CompMask;

    @State
    attributes!: GridAttribute[];

    @Mutation("updateMaskData")
    private updateColumnAttribute!: Function;

    columnAttibuteChange(value: ValueType, oldValue: ValueType, attribute: string) {
        this.updateColumnAttribute({ value, oldValue, attribute });
    }

    get showOthers(): boolean {
        return this.others?.length ? true : false;
    }

    @Action(PageDesignActions.UPDATE_COMP_OPTIONS)
    private updateCompOptions!: (param: EditorChangeEmitParam) => void;

    private attrClickHandle(attrName: string) {
        this.editingMask.modifyCompObjectAttr(attrName);
    }
}
